CREATE EXTENSION pg_stat_statements;

CREATE VIEW consultas_pesadas AS
SELECT query AS consulta,
       calls AS llamadas,
       round(total_exec_time::numeric, 2) AS total_ms,
       round(mean_exec_time::numeric, 2) AS promedio_ms,
       rows AS filas
FROM pg_stat_statements
ORDER BY total_exec_time DESC
LIMIT 10;

SELECT count(*) FROM validaciones WHERE tarifa = 870;
SELECT * FROM consultas_pesadas;

-- 1) Índice cubriente: ts para el rango, estacion_id para no visitar la tabla
CREATE INDEX validaciones_ts_estacion_idx ON validaciones (ts) INCLUDE (estacion_id);

-- 2) Estadísticas sobre la expresión
CREATE STATISTICS validaciones_hora ON (extract(hour FROM ts)) FROM validaciones;
ANALYZE validaciones;

-- 3) Anti join con NOT EXISTS
CREATE VIEW tarjetas_sin_junio AS
SELECT t.id, t.tipo, t.emitida
FROM tarjetas t
WHERE NOT EXISTS (SELECT 1
                  FROM validaciones v
                  WHERE v.tarjeta_id = t.id
                    AND v.ts >= '2026-06-01' AND v.ts < '2026-07-01');

